import { $$ } from "./utilities.ts";

// Restricts target arguments strictly to valid DOM query shapes or structural nodes
export type TargetInput = string | Element | readonly Element[] | NodeListOf<Element>;

export default class ObserverManager {
    // Readonly set typing locks down structural collection manipulations
    readonly #elements: Set<Element> = new Set<Element>();
    #observer: IntersectionObserver | null = null;
    
    // Explicitly readonly configuration prevents accidental parameter mutations at runtime
    readonly #defaultConfig: Readonly<IntersectionObserverInit> = {
        threshold: 0.20,
        rootMargin: "0px 0px -50px 0px"
    };

    constructor(customConfig: Readonly<IntersectionObserverInit> = {}) {
        const mergedConfig: IntersectionObserverInit = { ...this.#defaultConfig, ...customConfig };
        
        if (!("IntersectionObserver" in window)) {
            this.#revealFallback();
            return;
        }

        this.#observer = new IntersectionObserver(this.#handleReveal, mergedConfig);
        this.#initialize();
    }

    /**
     * Custom type guard validating element structure without dynamic prototype walking
     */
    #isElement(target: unknown): target is Element {
        return typeof target === "object" && target !== null && "nodeType" in target && (target as Node).nodeType === 1;
    }

    #initialize(): void {
        const staticElements = $$("[data-reveal]");
        const len = staticElements.length;
        if (len === 0) return;

        // Strict null assertion ensures compiler tracks observer stability
        const obs = this.#observer satisfies IntersectionObserver | null;
        if (!obs) return;

        const elSet = this.#elements;
        for (let i = 0; i < len; i++) {
            const el = staticElements[i];
            if (el) {
                elSet.add(el);
                obs.observe(el);
            }
        }
    }

    #handleReveal = (entries: readonly IntersectionObserverEntry[]): void => {
        const len = entries.length;
        const obs = this.#observer;
        if (!obs) return;
        
        const elSet = this.#elements;

        for (let i = 0; i < len; i++) {
            const entry = entries[i];
            if (entry?.isIntersecting) {
                const target = entry.target;
                target.classList.add("revealed");
                
                obs.unobserve(target);
                elSet.delete(target);
            }
        }
    };

    /**
     * Strongly typed observation gateway supporting strict functional signatures
     */
    public observe(target: TargetInput): void {
        if (!this.#observer) {
            this.#revealFallback(target);
            return;
        }

        let targetsToObserve: readonly Element[] | NodeListOf<Element> | null = null;

        if (typeof target === "string") {
            targetsToObserve = $$(target);
        } else if (Array.isArray(target)) {
            targetsToObserve = target;
        } else if (this.#isElement(target)) { 
            targetsToObserve = [target];
        } else if (typeof target === "object" && target !== null && "length" in target) {
            targetsToObserve = target as NodeListOf<Element>;
        }

        if (!targetsToObserve) return;

        const len = targetsToObserve.length;
        if (len === 0) return;

        const obs = this.#observer;
        const elSet = this.#elements;

        for (let i = 0; i < len; i++) {
            const el = targetsToObserve[i];
            if (el && !elSet.has(el)) {
                elSet.add(el);
                obs.observe(el);
            }
        }
    }

    #revealFallback(target: TargetInput | null = null): void {
        if (!target) {
            const elements = $$("[data-reveal]");
            const len = elements.length;
            for (let i = 0; i < len; i++) {
                elements[i]?.classList.add("revealed");
            }
            return;
        }

        if (typeof target === "string") {
            const elements = $$(target);
            const len = elements.length;
            for (let i = 0; i < len; i++) {
                elements[i]?.classList.add("revealed");
            }
        } else if (this.#isElement(target)) {
            target.classList.add("revealed");
        } else {
            const arr: readonly Element[] = Array.isArray(target) 
                ? target 
                : (Array.prototype.slice.call(target) as Element[]);
            const len = arr.length;
            for (let i = 0; i < len; i++) {
                arr[i]?.classList.add("revealed");
            }
        }
    }

    public destroy(): void {
        if (this.#observer) {
            this.#observer.disconnect();
            this.#observer = null;
        }
        this.#elements.clear();
    }
}